import React from 'react';
import { motion } from 'framer-motion';
import styled from 'styled-components';

/**
 * ACHIEVEMENT BADGES COMPONENT
 * 
 * This component creates visually appealing badges for major achievements,
 * hackathon wins, and professional milestones. It's designed to be reusable
 * across different pages of the portfolio.
 * 
 * Key Features:
 * - Animated badge reveals with stagger effects
 * - Trophy and medal icons for different achievement types
 * - Hover effects with detailed information
 * - Responsive design for mobile and desktop
 * - Color-coded badges based on achievement type
 * 
 * Usage:
 * - Can be embedded in About page, Home page, or dedicated Achievements section
 * - Supports different badge types: hackathon, certification, project, recognition
 */

const BadgesContainer = styled.div`
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  justify-content: center;
  margin: 2rem 0;
`;

const Badge = styled(motion.div)`
  position: relative;
  display: flex;
  align-items: center;
  padding: ${props => props.hasIcon ? '0.75rem 1.5rem' : '0.6rem 1.2rem'};
  border-radius: 25px;
  font-weight: 600;
  font-size: 0.85rem;
  cursor: pointer;
  transition: all 0.3s ease;
  border: 1px solid rgba(255, 255, 255, 0.1);
  
  /* Badge type styling - more subtle premium gradients */
  background: ${props => {
    switch (props.type) {
      case 'hackathon': return 'linear-gradient(135deg, rgba(255, 215, 0, 0.2), rgba(255, 165, 0, 0.2))';
      case 'certification': return 'linear-gradient(135deg, rgba(76, 175, 80, 0.2), rgba(69, 160, 73, 0.2))';
      case 'project': return 'linear-gradient(135deg, rgba(33, 150, 243, 0.2), rgba(25, 118, 210, 0.2))';
      case 'recognition': return 'linear-gradient(135deg, rgba(156, 39, 176, 0.2), rgba(123, 31, 162, 0.2))';
      default: return 'rgba(255, 255, 255, 0.05)';
    }
  }};
  
  color: ${props => {
    switch (props.type) {
      case 'hackathon': return '#FFD700';
      case 'certification': return '#81C784';
      case 'project': return '#64B5F6';
      case 'recognition': return '#BA68C8';
      default: return 'white';
    }
  }};

  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  
  &:hover {
    transform: translateY(-3px);
    background: ${props => {
      switch (props.type) {
        case 'hackathon': return 'rgba(255, 215, 0, 0.3)';
        case 'certification': return 'rgba(76, 175, 80, 0.3)';
        case 'project': return 'rgba(33, 150, 243, 0.3)';
        case 'recognition': return 'rgba(156, 39, 176, 0.3)';
        default: return 'rgba(255, 255, 255, 0.1)';
      }
    }};
    border-color: currentColor;
    box-shadow: 0 5px 15px rgba(0, 0, 0, 0.3);
  }
`;

const BadgeIcon = styled.div`
  margin-right: 0.5rem;
  font-size: 1rem;
  display: ${props => props.show ? 'block' : 'none'};
`;

const BadgeText = styled.span`
  white-space: nowrap;
`;

const TooltipContainer = styled.div`
  position: relative;
  display: inline-block;
`;

const Tooltip = styled.div`
  position: absolute;
  bottom: 120%;
  left: 50%;
  transform: translateX(-50%);
  background: rgba(0, 0, 0, 0.9);
  color: white;
  padding: 0.75rem 1rem;
  border-radius: 8px;
  font-size: 0.8rem;
  white-space: nowrap;
  opacity: 0;
  visibility: hidden;
  transition: all 0.3s ease;
  z-index: 1000;
  
  &:after {
    content: '';
    position: absolute;
    top: 100%;
    left: 50%;
    transform: translateX(-50%);
    border: 5px solid transparent;
    border-top-color: rgba(0, 0, 0, 0.9);
  }
  
  ${TooltipContainer}:hover & {
    opacity: 1;
    visibility: visible;
  }
`;

const AchievementBadges = ({ achievements = [] }) => {
  // Default achievements if none provided - showcasing Bhekumusa's key accomplishments
  const defaultAchievements = [
    {
      id: 1,
      text: 'Sappas Hackathon Winner',
      type: 'hackathon',
      icon: '',
      tooltip: 'Won the prestigious Sappas Hackathon competition'
    },
    {
      id: 201,
      text: 'SAP Integration Developer',
      type: 'certification',
      icon: '',
      tooltip: 'Professional certification in SAP integration development'
    },
    {
      id: 202,
      text: 'SAP S/4 Hana DB Admin',
      type: 'certification',
      icon: '',
      tooltip: 'Expertise in SAP S/4 Hana Database Administration'
    },
    {
      id: 203,
      text: 'IBM Project Manager',
      type: 'certification',
      icon: '',
      tooltip: 'IBM Professional Project Manager Certification'
    },
    {
      id: 2,
      text: 'SAP Tech Consultant',
      type: 'certification',
      icon: '',
      tooltip: 'SAP Tech Consultant Certification - Enterprise Solutions Expert'
    },
    {
      id: 3,
      text: 'AI/ML Specialist',
      type: 'certification',
      icon: '',
      tooltip: 'Machine Learning and AI Development Expert'
    },
    {
      id: 4,
      text: 'Full-Stack Developer',
      type: 'project',
      icon: '',
      tooltip: 'Proficient in both frontend and backend development'
    },
    {
      id: 5,
      text: 'Java Developer',
      type: 'certification',
      icon: '',
      tooltip: 'Recently added Java to professional toolkit'
    },
    {
      id: 6,
      text: 'C# Developer',
      type: 'certification',
      icon: '',
      tooltip: 'Recently mastered C# and .NET development'
    },
    {
      id: 7,
      text: 'Open Source Contributor',
      type: 'recognition',
      icon: '',
      tooltip: 'Active contributor to open source projects'
    },
    {
      id: 8,
      text: 'Cisco CCNA Certified',
      type: 'certification',
      icon: '',
      tooltip: 'Cisco Certified Network Associate - Professional networking expertise'
    }
  ];

  const badgesToShow = achievements.length > 0 ? achievements : defaultAchievements;

  return (
    <BadgesContainer>
      {badgesToShow.map((achievement, index) => (
        <TooltipContainer key={achievement.id}>
          <Badge
            type={achievement.type}
            hasIcon={!!achievement.icon}
            initial={{ opacity: 0, scale: 0.8, y: 20 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            transition={{ 
              duration: 0.5, 
              delay: index * 0.1,
              type: "spring",
              stiffness: 100
            }}
            whileHover={{ 
              scale: 1.05,
              y: -3
            }}
            whileTap={{ scale: 0.95 }}
          >
            <BadgeIcon show={!!achievement.icon}>{achievement.icon}</BadgeIcon>
            <BadgeText>{achievement.text}</BadgeText>
          </Badge>
          <Tooltip>{achievement.tooltip}</Tooltip>
        </TooltipContainer>
      ))}
    </BadgesContainer>
  );
};

export default AchievementBadges;
